use super::*;
use std::sync::atomic::{AtomicU64, Ordering};
static SERIAL:AtomicU64=AtomicU64::new(0);
#[test]
fn workspace_worker_replays_neutral_cancellation_progress_and_domain_outcomes(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();assert_eq!(MESSAGE_CAPACITY,fixture["messageCapacity"].as_u64().unwrap()as usize);
 for row in fixture["cases"].as_array().unwrap(){
  let root=PathBuf::from(std::env::var_os("SEMIO_TEST_ARTIFACT_DIR").expect("owned worker artifacts required")).join(format!("worker{}.{}",std::process::id(),SERIAL.fetch_add(1,Ordering::Relaxed)));assert!(root.to_string_lossy().encode_utf16().count()<220);std::fs::create_dir_all(&root).unwrap();let path=row["path"].as_str().unwrap();if row["kind"]=="load"{std::fs::write(root.join(path),row["text"].as_str().unwrap()).unwrap();}
  let request=match row["kind"].as_str().unwrap(){"list"=>Request::List(path.into()),"load"=>Request::Load(path.into()),"recovery-list"=>Request::RecoveryList(path.into()),_=>panic!("closed fixture command")};let(wake_send,wake_receive)=mpsc::channel();let receiver=spawn(root.clone(),request,Arc::new(AtomicBool::new(row["cancelled"].as_bool().unwrap())),Some(Arc::new(move||{let _=wake_send.send(());}))).unwrap();let mut messages=0;let outcome=loop{messages+=1;assert!(messages<10000);match receiver.recv_timeout(std::time::Duration::from_secs(5)).unwrap(){Message::Progress(_)=>{},Message::Finished(result)=>break match result{Ok(Response::List(_,entries))=>{assert!(entries.is_empty());"List"},Ok(Response::Load(document))=>{assert_eq!(document.text,row["text"].as_str().unwrap());"Load"},Ok(Response::RecoveryList(_,entries))=>{assert!(entries.is_empty());"RecoveryList"},Err(error)if error.kind==crate::ErrorKind::Cancelled=>"Cancelled",_=>panic!("unexpected domain outcome")}}};assert_eq!(outcome,row["outcome"].as_str().unwrap());wake_receive.recv_timeout(std::time::Duration::from_secs(5)).unwrap();drop(receiver);std::fs::remove_dir_all(root).unwrap();
 }
 let hierarchy:serde_json::Value=serde_json::from_str(include_str!("../../🎮️management/🧫️fixtures/🔣️.json")).unwrap();for row in hierarchy["hierarchy"].as_array().unwrap(){assert_eq!(path_contains(row["root"].as_str().unwrap(),row["path"].as_str().unwrap()),row["contains"].as_bool().unwrap());}
 let(send,receive)=mpsc::sync_channel(MESSAGE_CAPACITY);let wakes=Arc::new(AtomicU64::new(0));let counter=wakes.clone();let wake:Option<Arc<dyn Fn()+Send+Sync>>=Some(Arc::new(move||{counter.fetch_add(1,Ordering::Relaxed);}));let saturation=&fixture["saturation"];let publishes=saturation["publishes"].as_u64().unwrap();for completed in 0..publishes{publish_progress(&send,Progress{stage:crate::Stage::Reading,completed,total:Some(publishes)},&wake);}assert_eq!(wakes.load(Ordering::Relaxed),saturation["wakes"].as_u64().unwrap());for expected in 0..MESSAGE_CAPACITY{assert!(matches!(receive.try_recv().unwrap(),Message::Progress(progress)if progress.completed==expected as u64));}assert!(receive.try_recv().is_err());publish_progress(&send,Progress{stage:crate::Stage::Complete,completed:publishes,total:Some(publishes)},&wake);assert_eq!(wakes.load(Ordering::Relaxed),MESSAGE_CAPACITY as u64+1);

}
